import { clamp, lerp, smooth } from '../../common/math';

/* [immersion] Mô phỏng dìm đốt hầm số 3 (đốt giữa, 120 m): state machine như SwingController của Cầu sông Hàn.
   IDLE → FLOAT_IN (tàu kéo dắt đốt nổi vào) → POSITION (neo định vị) → BALLAST (bơm nước dằn, chìm dần)
   → PULL_JOINT (kích kéo áp khít, gioăng GINA bị nén) → BACKFILL (lấp cát, phủ đá hộc) → DONE.
   Phát event immerseStart / immerseDone / stateChange. */
export const IM_STATES = ['IDLE', 'FLOAT_IN', 'POSITION', 'BALLAST', 'PULL_JOINT', 'BACKFILL', 'DONE'] as const;
export type ImState = typeof IM_STATES[number];

/* Thời gian thật từng giai đoạn (giây), chia cho hệ số tăng tốc */
const DUR: Record<Exclude<ImState, 'IDLE'>, number> = { FLOAT_IN: 70, POSITION: 45, BALLAST: 100, PULL_JOINT: 40, BACKFILL: 70, DONE: 15 };
/* Độ cao nâng của đốt khi nổi: nóc đốt cách mặt nước +0,8 m; đốt cao 8,5 m, nóc lúc hoàn thiện ở −7,6 m ⇒ nâng ≈ 8,4 m */
export const FLOAT_LIFT = 8.4, APPROACH = 230, STANDOFF = 26, GAP = 3.2;

export class ImmersionController extends EventTarget {
  state: ImState = 'IDLE';
  t = 0;
  speed = 10;
  /* đầu ra, vị trí đốt 3 so với vị trí hoàn thiện */
  zOff = 0; lift = 0; gap = 0;
  fill = 1;        // 0 → 1: mức lấp đá hộc phủ nóc
  tugs = 0;        // 0: đang kéo; 1: tàu kéo đã rút về
  jack = 0;        // 0 → 1: kích kéo đang co
  fromTour = false;
  get busy() { return this.state !== 'IDLE'; }
  start(speed?: number) {
    if (this.state !== 'IDLE') return false;
    if (speed) this.speed = speed;
    this.go('FLOAT_IN'); this.dispatchEvent(new Event('immerseStart'));
    return true;
  }
  go(s: ImState) {
    this.state = s; this.t = 0;
    this.dispatchEvent(new CustomEvent<ImState>('stateChange', { detail: s }));
    if (s === 'IDLE') this.dispatchEvent(new Event('immerseDone'));
  }
  /* Tư thế hoàn thiện (khi không mô phỏng) */
  private rest() { this.zOff = 0; this.lift = 0; this.gap = 0; this.fill = 1; this.tugs = 1; this.jack = 0; }
  update(dt: number) {
    if (this.state === 'IDLE') { this.rest(); return; }
    this.t += dt * this.speed;
    const k = clamp(this.t / DUR[this.state], 0, 1);
    switch (this.state) {
      case 'FLOAT_IN':
        this.zOff = lerp(-APPROACH, -STANDOFF, smooth(k)); this.lift = FLOAT_LIFT; this.gap = GAP; this.fill = 0; this.tugs = 0; this.jack = 0;
        if (k >= 1) this.go('POSITION');
        break;
      case 'POSITION':
        this.zOff = lerp(-STANDOFF, 0, smooth(k)); this.lift = FLOAT_LIFT + Math.sin(this.t * 0.7) * 0.05 * (1 - k);
        if (k >= 1) this.go('BALLAST');
        break;
      case 'BALLAST':
        this.zOff = 0; this.lift = lerp(FLOAT_LIFT, 0.5, smooth(k)); this.tugs = smooth(clamp(k * 2, 0, 1));
        if (k >= 1) this.go('PULL_JOINT');
        break;
      case 'PULL_JOINT':
        this.lift = lerp(0.5, 0, smooth(clamp(k * 2, 0, 1))); this.gap = lerp(GAP, 0, smooth(clamp((k - 0.2) / 0.8, 0, 1)));
        this.jack = Math.sin(Math.PI * clamp(k, 0, 1)); this.tugs = 1;
        if (k >= 1) this.go('BACKFILL');
        break;
      case 'BACKFILL':
        this.lift = 0; this.gap = 0; this.jack = 0; this.fill = smooth(k);
        if (k >= 1) this.go('DONE');
        break;
      case 'DONE':
        this.fill = 1;
        if (k >= 1) { this.rest(); this.go('IDLE'); }
        break;
    }
  }
}
import * as THREE from 'three';
import { renderer, scene } from '../../core/renderer';
import { MAT } from '../../core/materials';
import { canvasTex } from '../../core/textures';
import { water } from '../../core/water';
import { CONFIG } from '../../config';
import { HR, HR_HOLES, hrRoadY, hrBedY, hrTrenchY } from './profile';
import type { HrMaterials } from './materials';

/* [cutaway] Hai chế độ xem dưới lòng đất:
   • Mặt cắt địa chất (section): bóc dải đất phía Bắc mặt cắt dọc tim ống Nam, hiện tấm địa chất, nước trong suốt.
     Bóc bằng clippingPlanes + clipIntersection (4 mặt phẳng ⇒ một hình hộp bị loại bỏ), riêng nước dùng discard trong shader.
   • Nước trong (glass): chỉ làm nước trong suốt để thấy hào nạo vét và đốt hầm đang dìm (dùng khi mô phỏng dìm đốt hầm).
   Mặt phẳng cắt gán cố định từ khi dựng (D-018): đổi clippingPlanes/clipIntersection làm mọi vật liệu biên dịch lại shader (~45 vật liệu + nhà,
   giật vài giây). Tắt = đẩy mặt phẳng đầu ra rất xa: với clipIntersection, điểm chỉ bị cắt khi nằm phía âm của CẢ 4 mặt phẳng ⇒ không điểm nào bị cắt. */
export const CUT_X = HR.approachHalf + 40;     // m — nửa chiều dài vùng bóc
export const CUT_Z = HR.z + HR.cutZ;           // m — mặt cắt (thế giới), qua tim ống Nam
export const CUT_STRIP = 110;                  // m — bề rộng dải bị bóc, phía Bắc mặt cắt
const Y_TOP = 8, Y_BOT = -45;
const PLANE_OFF = 1e7;                         // m — hằng số mặt phẳng đầu khi tắt mặt cắt: mọi điểm nằm phía dương ⇒ không cắt

/* Nhãn 3D trên mặt cắt: khóa i18n + tọa độ thế giới */
export const CUT_LABELS: { key: string; pos: [number, number, number] }[] = [
  { key: 'hrLblElements', pos: [-150, -13, CUT_Z] },
  { key: 'hrLblGina', pos: [60, -10, CUT_Z] },
  { key: 'hrLblBed', pos: [150, -4.6, CUT_Z] },
  { key: 'hrLblPump', pos: [-9, -12, HR.z + HR.tubeFar - 0.7] },
  { key: 'hrLblCover', pos: [400, -4, CUT_Z] },
  { key: 'hrLblRamp', pos: [600, 1.5, CUT_Z] },
  { key: 'hrLblFlood', pos: [HR.rampHalf + 7, 4.4, CUT_Z] }
];

const LAYERS: [number, string, string][] = [[-2, '#d8c58f', 'cát san lấp'], [-9, '#c3a869', 'cát pha'], [-22, '#7f8f72', 'sét yếu'], [-34, '#8d7058', 'sét cứng'], [Y_BOT, '#6b6865', 'đá phong hoá']];

function drawGeology() {
  const W = 4096, H = Math.round((Y_TOP - Y_BOT) * 12), kx = W / (2 * CUT_X), ky = 12;
  const px = (x: number) => (CUT_X - x) * kx, py = (y: number) => (Y_TOP - y) * ky;   // đông ở bên trái khi nhìn từ phía Bắc
  return canvasTex(W, H, (g) => {
    const surf = (x: number) => (Math.abs(x) <= 264 ? hrBedY(x) : CONFIG.landY);
    // các lớp đất, mỗi cột 1 px
    for (let c = 0; c < W; c++) {
      const x = CUT_X - (c + 0.5) / kx, s = surf(x);
      let top = s;
      for (const [bot, col] of LAYERS) {
        if (top <= bot) continue;
        g.fillStyle = col; g.fillRect(c, py(top), 1.2, py(bot) - py(top) + 1); top = bot;
      }
      if (Math.abs(x) <= 264) { g.fillStyle = 'rgba(70,150,185,0.55)'; g.fillRect(c, py(0), 1.2, py(s) - py(0)); }   // cột nước sông
    }
    // lớp đá hộc trong hào nạo vét
    g.fillStyle = '#8b8880';
    for (let c = 0; c < W; c++) { const x = CUT_X - (c + 0.5) / kx; if (Math.abs(x) <= 264) g.fillRect(c, py(hrBedY(x)), 1.2, py(hrTrenchY(x)) - py(hrBedY(x))); }
    // vỏ hầm: bản nóc và bản đáy (cắt qua), ống rỗng
    for (let c = 0; c < W; c++) {
      const x = CUT_X - (c + 0.5) / kx, a = Math.abs(x), R = hrRoadY(x);
      if (a <= HR.coverHalf) {
        g.fillStyle = '#b6b3ab'; g.fillRect(c, py(R + HR.roofTop), 1.2, py(R + HR.clear) - py(R + HR.roofTop) + 1);
        g.fillRect(c, py(R), 1.2, py(R - HR.slabBelow) - py(R) + 1);
      } else if (a <= HR.rampHalf) {
        g.clearRect(c, 0, 1.2, py(R));                                               // máng hầm hở: bỏ đất phía trên sàn
        g.fillStyle = '#b6b3ab'; g.fillRect(c, py(R), 1.2, py(R - HR.slabBelow) - py(R) + 1);
      }
    }
    g.globalCompositeOperation = 'destination-out';                                  // lòng ống xe: để trống cho thấy nội thất 3D
    for (let c = 0; c < W; c++) { const x = CUT_X - (c + 0.5) / kx; if (Math.abs(x) <= HR.coverHalf) { const R = hrRoadY(x); g.fillRect(c, py(R + HR.clear), 1.2, py(R) - py(R + HR.clear)); } }
    g.globalCompositeOperation = 'source-over';
    // đường mặt đất, mực nước, lưới cao độ
    g.strokeStyle = 'rgba(30,30,30,0.7)'; g.lineWidth = 2; g.beginPath();
    for (let c = 0; c < W; c += 2) { const x = CUT_X - c / kx, y = Math.abs(x) <= 264 ? hrBedY(x) : CONFIG.landY; c ? g.lineTo(c, py(y)) : g.moveTo(c, py(y)); }
    g.stroke();
    g.strokeStyle = 'rgba(255,255,255,0.28)'; g.fillStyle = 'rgba(255,255,255,0.8)'; g.lineWidth = 1; g.font = '14px "JetBrains Mono", monospace';
    for (let y = 0; y >= Y_BOT; y -= 10) { g.beginPath(); g.moveTo(0, py(y)); g.lineTo(W, py(y)); g.stroke(); g.fillText(`${y} m`, 8, py(y) - 3); g.fillText(`${y} m`, W - 56, py(y) - 3); }
    g.setLineDash([10, 8]); g.strokeStyle = 'rgba(80,170,255,0.9)'; g.beginPath(); g.moveTo(px(CUT_X), py(0.4)); g.lineTo(px(264), py(0.4)); g.moveTo(px(-264), py(0.4)); g.lineTo(px(-CUT_X), py(0.4)); g.stroke();   // mực nước ngầm
  });
}
/* Dải cột chữ cái cho tên lớp đất (ghi bên trái bảng) */
export class Cutaway {
  section = false; glass = false;
  readonly planes: THREE.Plane[];
  readonly plane: THREE.Mesh;
  private mats: THREE.Material[] = [];

  constructor(M: HrMaterials) {
    renderer.localClippingEnabled = true;
    // vùng bị bóc: x ∈ (−CUT_X, CUT_X), z ∈ (CUT_Z − CUT_STRIP, CUT_Z) — clipIntersection nên chỉ phần nằm ngoài CẢ 4 mặt phẳng mới bị cắt
    this.planes = [
      new THREE.Plane(new THREE.Vector3(-1, 0, 0), PLANE_OFF), new THREE.Plane(new THREE.Vector3(1, 0, 0), -CUT_X),
      new THREE.Plane(new THREE.Vector3(0, 0, -1), CUT_Z - CUT_STRIP), new THREE.Plane(new THREE.Vector3(0, 0, 1), -CUT_Z)
    ];
    // tấm mặt cắt địa chất đặt sát mặt phía Nam, quay mặt về phía Bắc (nơi camera đứng)
    const tex = drawGeology(); M.textures.push(tex);
    this.plane = new THREE.Mesh(new THREE.PlaneGeometry(CUT_X * 2, Y_TOP - Y_BOT), new THREE.MeshBasicMaterial({ map: tex, transparent: true, alphaTest: 0.04, fog: false }));
    this.plane.rotation.y = Math.PI; this.plane.position.set(0, (Y_TOP + Y_BOT) / 2, CUT_Z + 0.04);
    this.plane.visible = false; this.plane.name = 'hr-geology'; this.plane.layers.set(1); scene.add(this.plane);
    this.patchWater();
    // vật liệu bị bóc: đất, đường, cây, đèn, nhà (vật liệu riêng của buildCity) và hầm
    const set = new Set<THREE.Material>([MAT.land, MAT.sand, MAT.paver, MAT.stone, MAT.grass, MAT.road, MAT.road2, MAT.trunk, MAT.leaf, MAT.palm, MAT.lampPole, MAT.bulb,
      MAT.vehicle, MAT.glass, MAT.headLamp, MAT.tailLamp, MAT.hull, MAT.boatCabin, MAT.boatRoof,
      M.concrete, M.bore, M.roadIn, M.roadOut, M.louver, M.brick, M.wave, M.bed, M.rubble, M.steel, M.lampThr, M.lampIn, M.lampCorr, M.fan, M.sos, M.extinguisher, M.door, M.exit, M.laneGreen, M.guide, M.equip, M.grate, M.basket]);
    scene.traverse((o) => { const i = o as THREE.InstancedMesh; if (i.isInstancedMesh && i.parent && (i.parent as THREE.LOD).isLOD) set.add(i.material as THREE.Material); });
    this.mats = [...set];
    for (const m of this.mats) { m.clippingPlanes = this.planes; m.clipIntersection = true; m.needsUpdate = true; }   // lúc dựng, trước lần biên dịch đầu
  }
  /* Nước: bỏ các điểm nằm trong máng hầm hở (nước trải vô hạn ở y = 0 sẽ lọt vào máng) và trong vùng bóc khi bật mặt cắt */
  private patchWater() {
    const mat = water.material as THREE.ShaderMaterial;
    mat.uniforms.uHoles = { value: HR_HOLES.map((h) => new THREE.Vector4(h.x0, h.z0, h.x1, h.z1)) };
    mat.uniforms.uCut = { value: new THREE.Vector4(-CUT_X, CUT_Z - CUT_STRIP, CUT_X, CUT_Z) };
    mat.uniforms.uCutOn = { value: 0 };
    mat.fragmentShader = mat.fragmentShader.replace('void main() {', `uniform vec4 uHoles[${HR_HOLES.length}]; uniform vec4 uCut; uniform float uCutOn;
      bool inRect(vec4 r, vec2 p) { return p.x > r.x && p.x < r.z && p.y > r.y && p.y < r.w; }
      void main() {
        vec2 wp = worldPosition.xz;
        for (int i = 0; i < ${HR_HOLES.length}; i++) if (inRect(uHoles[i], wp)) discard;
        if (uCutOn > 0.5 && inRect(uCut, wp)) discard;`);
    mat.needsUpdate = true;
  }
  setSection(on: boolean) {
    if (on === this.section) return;
    this.section = on; this.plane.visible = on;
    this.planes[0].constant = on ? -CUT_X : PLANE_OFF;
    (water.material as THREE.ShaderMaterial).uniforms.uCutOn.value = on ? 1 : 0;
    this.applyWater();
  }
  setGlass(on: boolean) { if (on === this.glass) return; this.glass = on; this.applyWater(); }
  private applyWater() {
    const clear = this.section || this.glass, mat = water.material as THREE.ShaderMaterial;
    mat.transparent = clear; mat.depthWrite = !clear; mat.uniforms.alpha.value = clear ? 0.4 : 1;
  }
}
import * as THREE from 'three';
import { HR, hrBedY, hrTrenchY, hrTrenchTop } from './profile';
import type { HrMaterials } from './materials';

/* [riverbed] Đáy sông dọc tuyến hầm (chỉ thấy khi nước trong suốt hoặc ở chế độ mặt cắt): đáy nông dần về kè, hào nạo vét cho
   hầm dìm, và lớp đá hộc phủ nóc từng đốt (dải ribbon mỗi đốt để mô phỏng dìm đốt số 3 có thể ẩn riêng).
   Tọa độ cục bộ của group hầm (z = 0 ở tim tuyến). */
const ZMIN = -2600 - HR.z, ZMAX = 2600 - HR.z, XB = 264, STEP = 6;

export interface Riverbed { group: THREE.Group; ribbons: THREE.Mesh[] }
export function hrBuildRiverbed(M: HrMaterials): Riverbed {
  const group = new THREE.Group(); group.name = 'hr-riverbed';
  // lưới đáy sông: mỗi hàng ngang x có 6 cột z: biên, mép miệng hào, chân hào (×2)
  const xs: number[] = []; for (let x = -XB; x <= XB + 1e-6; x += STEP) xs.push(x);
  const pos: number[] = [], idx: number[] = [], C = 6;
  for (const x of xs) {
    const bed = hrBedY(x), tb = hrTrenchY(x), top = hrTrenchTop(x), bot = HR.trenchBottomHalf;
    for (const [z, y] of [[ZMIN, bed], [-top, bed], [-bot, tb], [bot, tb], [top, bed], [ZMAX, bed]]) pos.push(x, y, z);
  }
  for (let r = 0; r < xs.length - 1; r++) for (let c = 0; c < C - 1; c++) {
    const a = r * C + c, b = a + 1, d = (r + 1) * C + c, e = d + 1;
    idx.push(a, b, d, b, e, d);
  }
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3)); g.setIndex(idx); g.computeVertexNormals();
  const bed = new THREE.Mesh(g, M.bed); bed.receiveShadow = true; bed.name = 'hr-bed'; group.add(bed);

  // đá hộc phủ nóc: dải theo bề rộng miệng hào, nằm ngang mực đáy sông; mỗi đốt một dải
  const ribbons: THREE.Mesh[] = [];
  for (let i = 0; i < HR.elements; i++) {
    const lo = Math.max(HR.elementEdges[i], -XB), hi = Math.min(HR.elementEdges[i + 1], XB), n = Math.max(1, Math.ceil((hi - lo) / STEP));
    const p: number[] = [], uv: number[] = [], ix: number[] = [];
    for (let k = 0; k <= n; k++) {
      const x = lo + (hi - lo) * k / n, y = hrBedY(x) + 0.04, w = hrTrenchTop(x);
      p.push(x, y, -w, x, y, w); uv.push(x / 8, -w / 8, x / 8, w / 8);
      if (k < n) { const a = k * 2; ix.push(a, a + 1, a + 2, a + 1, a + 3, a + 2); }
    }
    const rg = new THREE.BufferGeometry();
    rg.setAttribute('position', new THREE.Float32BufferAttribute(p, 3)); rg.setAttribute('uv', new THREE.Float32BufferAttribute(uv, 2));
    rg.setIndex(ix); rg.computeVertexNormals();
    const m = new THREE.Mesh(rg, M.rubble); m.receiveShadow = true; m.name = `hr-rubble-${i + 1}`;
    ribbons.push(m); group.add(m);
  }
  return { group, ribbons };
}
import * as THREE from 'three';
import { mergeGeometries } from 'three/addons/utils/BufferGeometryUtils.js';
import { prepColored, bentBox } from '../../common/geometry';
import { smooth, clamp } from '../../common/math';
import { HR, hrRoadY } from './profile';

/* [shell] Vỏ hầm: tiết diện hai ống xe + hành lang thoát nạn, đùn dọc trục X rồi uốn theo trắc dọc.
   Tiết diện đối xứng qua z = 0 (ExtrudeGeometry của three đảo dấu z sau khi xoay, không ảnh hưởng). */
const V = (z: number, y: number) => new THREE.Vector2(z, y);
const BAND = 3.0;   // m — tường ốp tấm sáng màu tới 3 m, phía trên sơn tối

/* Đùn tiết diện (z, y) có lỗ dọc trục X từ x0 tới x1, uốn theo mặt đường hrRoadY */
export function extrudeShape(shape: THREE.Shape, x0: number, x1: number, steps: number) {
  const g = new THREE.ExtrudeGeometry(shape, { depth: x1 - x0, steps, bevelEnabled: false });
  g.rotateY(Math.PI / 2); g.translate(x0, 0, 0);
  const p = g.attributes.position;
  for (let i = 0; i < p.count; i++) p.setY(i, p.getY(i) + hrRoadY(p.getX(i)));
  g.deleteAttribute('uv'); g.deleteAttribute('normal'); g.computeVertexNormals();
  return g;
}
/* Tiết diện 31,2 × 8,5 m: lỗ ống Nam, ống Bắc và hành lang. Thêm đỉnh ở cao độ 3 m để tô hai dải màu tường */
export function boreShape() {
  const W = HR.halfWidth, top = HR.roofTop, bot = -HR.slabBelow;
  const s = new THREE.Shape([V(-W, bot), V(W, bot), V(W, top), V(-W, top)]);
  const hole = (z0: number, z1: number, h: number, band: boolean) => new THREE.Path(band
    ? [V(z0, 0), V(z1, 0), V(z1, BAND - 0.02), V(z1, BAND), V(z1, h), V(z0, h), V(z0, BAND), V(z0, BAND - 0.02)]
    : [V(z0, 0), V(z1, 0), V(z1, h), V(z0, h)]);
  s.holes.push(hole(HR.tubeNear, HR.tubeFar, HR.clear, true), hole(-HR.tubeFar, -HR.tubeNear, HR.clear, true), hole(-HR.corridorHalf, HR.corridorHalf, HR.corridorClear, false));
  return s;
}
/* Độ sáng nền theo vị trí: vùng ngưỡng 80 m cuối hầm kín sáng nhất, giảm dần vào trong */
export const boreLevel = (x: number) => 0.5 + 0.5 * smooth(clamp((Math.abs(x) - 330) / 90, 0, 1));
/* Màu đỉnh (xám đồng nhất): mặt ngoài bê tông trần; trong lòng ống: tường ốp sáng, trần sơn tối, sàn xám */
export function boreColor(x: number, y: number, z: number): number {
  const rel = y - hrRoadY(x);
  if (rel <= -HR.slabBelow + 0.02 || rel >= HR.roofTop - 0.02 || Math.abs(z) >= HR.halfWidth - 0.02) return 0.8;
  const f = boreLevel(x);
  if (rel >= BAND - 0.005) return 0.4 * f;
  if (rel <= 0.02) return 0.5 * f;
  return 0.95 * f;
}
/* Vỏ một đoạn hầm kín [x0, x1] */
export function boreShell(x0: number, x1: number) {
  return prepColored(extrudeShape(boreShape(), x0, x1, Math.max(1, Math.ceil((x1 - x0) / 6))), boreColor);
}
/* Vòng gioăng GINA/Omega ở khe nối hai đốt: dải sẫm quanh chu vi, nhô 6 cm */
export function jointRing(x: number) {
  const W = HR.halfWidth, H = HR.slabBelow + HR.roofTop, yMid = (HR.roofTop - HR.slabBelow) / 2, L = 0.5;
  const parts = [
    bentBox(L, 0.12, W * 2 + 0.12, x, HR.roofTop, 0, 1, hrRoadY), bentBox(L, 0.12, W * 2 + 0.12, x, -HR.slabBelow, 0, 1, hrRoadY),
    bentBox(L, H + 0.12, 0.12, x, yMid, W, 1, hrRoadY), bentBox(L, H + 0.12, 0.12, x, yMid, -W, 1, hrRoadY)
  ];
  return prepColored(mergeGeometries(parts.map((g) => g.toNonIndexed())), () => 0.16);
}

