  const road = new THREE.Mesh(mergeGeometries([
    roadStrip(x0, x1, W, HR.tubeCenter, 0.03, segs, hrRoadY), roadStrip(x0, x1, W, -HR.tubeCenter, 0.03, segs, hrRoadY, true)
  ]), M.roadIn);
